function guess(navLang) {
  const code = String(navLang || 'en').toLowerCase().slice(0, 2);
  return CODES.includes(code) ? code : 'en';
}

function t(lang, key, vars) {
  const row = S[key];
  if (!row) return key;
  const i = Math.max(0, CODES.indexOf(lang));
  let text = row[i] || row[0];
  if (vars) for (const [k, v] of Object.entries(vars)) text = text.split(`{${k}}`).join(String(v));
  return text;
}

module.exports = { t, guess, LANGS };
